package com.primehr.rsp.selection.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import org.hibernate.annotations.Nationalized;import java.time.Instant;
@Entity @Table(name="rsp_selection_notice") public class SelectionNotice extends RspAuditedEntity{public enum Kind{SELECTED,NOT_SELECTED,NO_SELECTION,DEFERRED,SUPERSEDED}@Column(name="selection_case_id",nullable=false,length=36)private String selectionCaseId;@Column(name="application_id",nullable=false,length=36)private String applicationId;@Column(name="applicant_id",nullable=false,length=36)private String applicantId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Kind kind;@Nationalized @Column(name="safe_text",nullable=false,length=2000)private String safeText;@Column(name="released_at",nullable=false)private Instant releasedAt;@Column(name="current_notice_key",length=100)private String currentNoticeKey;protected SelectionNotice(){}public SelectionNotice(String agency,String selection,String application,String applicant,Kind kind,String safeText,Instant at){super(agency);selectionCaseId=requiredText(selection,"selectionCaseId");applicationId=requiredText(application,"applicationId");applicantId=requiredText(applicant,"applicantId");this.kind=java.util.Objects.requireNonNull(kind);this.safeText=requiredText(safeText,"safeText");releasedAt=java.util.Objects.requireNonNull(at);currentNoticeKey=application;}public void supersede(){kind=Kind.SUPERSEDED;currentNoticeKey=null;}public String getSelectionCaseId(){return selectionCaseId;}public String getApplicationId(){return applicationId;}public String getApplicantId(){return applicantId;}public Kind getKind(){return kind;}public String getSafeText(){return safeText;}public Instant getReleasedAt(){return releasedAt;}}
